import{_ as a,o as s,c as r,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Server modpacks","description":"","frontmatter":{"pageId":"players/modpacks","contentRevision":1},"headers":[],"relativePath":"en/players/modpacks.md","filePath":"en/players/modpacks.md"}'),i={name:"en/players/modpacks.md"};function o(n,e,l,d,c,h){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="server-modpacks" tabindex="-1">Server modpacks <a class="header-anchor" href="#server-modpacks" aria-label="Permalink to &quot;Server modpacks&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>The difference dialog compares server requirements with installed mods and load order. Read the mismatch list first. The server may require exact files and shared settings, not merely matching mod names.</p><p>If server delivery is available, inspect the offered package before downloading it. Downloading and applying are separate: close the game before replacing in-use files. Restart after applying, then repeat the check. Do not overwrite a verified package with an arbitrary Workshop version.</p><p>Without a published archive, install requirements following the administrator&#39;s instructions. Back up your configuration before replacing settings.</p><h3 id="workshop-fix-the-mismatch" tabindex="-1">Workshop: fix the mismatch <a class="header-anchor" href="#workshop-fix-the-mismatch" aria-label="Permalink to &quot;Workshop: fix the mismatch&quot;">​</a></h3><ol><li>Read each category: missing mods, wrong versions, changed files, forbidden mods, load order and shared settings. A newer local version can mean the server must update; the client cannot invent an older Workshop revision.</li><li>Choose <strong>Fix and restart</strong>. It subscribes to missing Workshop mods, waits for Steam, orders the list, disables refused extras and stages the shared settings. The old list is backed up as <code>Config/ModsConfig.rimlink-backup.xml</code>.</li><li>After the restart, Rimlink resumes joining. A password account still asks for its password: it is not stored. If files still differ, send the mismatch details to the administrator instead of bypassing the check.</li><li>Server settings remain active on subsequent starts, including single-player games. Use the main-menu <strong>Mod settings of [server] in effect: use mine</strong> action and restart to return to personal settings. Personal settings files are not overwritten.</li></ol><h3 id="server-archive-download-verify-recover" tabindex="-1">Server archive: download, verify, recover <a class="header-anchor" href="#server-archive-download-verify-recover" aria-label="Permalink to &quot;Server archive: download, verify, recover&quot;">​</a></h3><ol><li>Beside the saved server choose <strong>Download server modpack</strong>, or use the mismatch dialog. Verify the certificate before entering the server password. Review mods, archive/expanded sizes and reuse/install actions; separately approve mod code and shared settings.</li><li>Let the client finish its resumable download and SHA-256/path/size verification. New mods use separate <code>Mods/rimlink-managed-…</code> folders. An exact installed copy can be reused; conflicting or duplicate unmanaged copies block installation and show their paths. They are never overwritten. Extra gameplay mods are disabled, not deleted.</li><li>The complete settings snapshot is staged before one restart. Matching loaded mods/settings and successful login are required for verification. Failure preserves installed files and backups for retry; no restart loop is expected.</li><li>If interrupted, use <strong>Roll back installation</strong> from the server list for a pending journal. Preserve <code>Rimlink/install-journal.json</code>, the pending marker and backups. External modifications stop automatic recovery: resolve the indicated files manually with the game closed. Loaded assemblies cannot be replaced or restored safely.</li></ol><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The game, Core and DLC are not included. A downloader working without Steam is not proof of tested GOG gameplay. Do not bypass a hash mismatch by editing the manifest.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./../compatibility">Versions and compatibility</a></li><li><a href="./../admins/modpacks">Managing modpacks</a></li><li><a href="./install">Installing the mod</a></li></ul>',14)])])}const f=a(i,[["render",o]]);export{p as __pageData,f as default};
